<?php if($message):?><p class="message"><?=escapeHtml($message)?></p><?php endif;?>
<section class="panel"><h2>Create staff account</h2><p>Initial password: <strong>thelewiscollege</strong>.</p><form method="post" action="<?=escapeHtml(applicationUrl('/registrar/staff_action.php'))?>"><input type="hidden" name="csrf_token" value="<?=escapeHtml($csrfToken)?>"><input type="email" name="email" pattern=".+@thelewiscollege\.edu\.ph" placeholder="Gsuite Address" required><select name="role"><?php foreach(['ORG_STAFF','DEAN','SASO_STAFF','STUDENT_COUNCIL_STAFF','LIBRARY_STAFF','BOOKSTORE_STAFF','CLINIC_STAFF','FACILITIES_STAFF','COMLAB_STAFF','ACCOUNTING_STAFF','REGISTRAR'] as $role):?><option value="<?=$role?>"><?=escapeHtml(str_replace('_',' ',$role))?></option><?php endforeach;?></select><select name="organization_id"><option value="">College (Dean/Organization Staff)</option><?php foreach($organizations as $org):?><option value="<?=(int)$org['id']?>"><?=escapeHtml($org['code'].' - '.$org['name'])?></option><?php endforeach;?></select><button name="action" value="create">Create Staff Account</button></form></section>
<section class="panel"><p>Only the Registrar can change office passwords.</p><div class="table-wrap"><table><thead><tr><th>Role</th><th>College</th><th>Gsuite Address</th><th>Status</th><th>Last Login</th><th>Registrar Controls</th></tr></thead><tbody><?php foreach($staff as $account):?><tr><td><?=escapeHtml(str_replace('_',' ',$account['role']))?></td><td><?=escapeHtml($account['colleges']??'—')?></td><td><?=escapeHtml($account['email'])?></td><td><?=escapeHtml($account['status'])?></td><td><?=escapeHtml($account['last_login_at']??'Never')?></td><td><form method="post" action="<?=escapeHtml(applicationUrl('/registrar/staff_action.php'))?>"><input type="hidden" name="csrf_token" value="<?=escapeHtml($csrfToken)?>"><input type="hidden" name="user_id" value="<?=(int)$account['id']?>"><input type="email" name="email" pattern=".+@thelewiscollege\.edu\.ph" value="<?=escapeHtml($account['email'])?>" required><button name="action" value="update_email">Save Email</button><input type="password" name="new_password" minlength="8" placeholder="New password"><button name="action" value="change_password">Change Password</button><button name="action" value="reset_default">Reset to Default</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
</main></body></html>
